function deferred(): { promise: Promise<void>; resolve: () => void } {
	let resolvePromise!: () => void;
	let resolved = false;
	const promise = new Promise<void>(resolve => { resolvePromise = resolve; });
	return {
		promise,
		resolve() {
			if (resolved) return;
			resolved = true;
			resolvePromise();
		},
	};
}

